(async () => {
  const { existsSync, writeFileSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  if (!existsSync(inputPath)) {
    const pngBase64 = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+X2V8AAAAASUVORK5CYII=';
    const buf = Buffer.from(pngBase64, 'base64');
    writeFileSync(inputPath, buf);
  }
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const { createWriteStream } = await import('node:fs');
  const { convert, sizes } = await import('image-to-pdf');
  const inputPath = globalThis.inputPath;
  const outputPath = globalThis.outputPath;
  await new Promise((resolve, reject) => {
    const pdfStream = convert([inputPath], sizes.A4);
    const out = createWriteStream(outputPath);
    pdfStream.pipe(out);
    out.on('finish', resolve);
    out.on('error', reject);
    pdfStream.on('error', reject);
  });
})();

